import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"网站更新机制","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/website-update.md","filePath":"zh/release/website-update.md"}'),d={name:"zh/release/website-update.md"};function l(c,e,i,r,n,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="网站更新机制" tabindex="-1">网站更新机制 <a class="header-anchor" href="#网站更新机制" aria-label="Permalink to &quot;网站更新机制&quot;">​</a></h1><p>公开站点是本仓库的 <strong>gh-pages 分支</strong> （<a href="https://ocos.cubestudio.cn/%EF%BC%8CGitHub" target="_blank" rel="noreferrer">https://ocos.cubestudio.cn/，GitHub</a> Pages）。门面是静态的： <code>assets/site-data.js</code> 携带版本数据，<code>download.html</code> / <code>index.html</code> 渲染它，<code>downloads/</code> 存放资产副本。</p><h2 id="发布时的更新-每次发布" tabindex="-1">发布时的更新（每次发布） <a class="header-anchor" href="#发布时的更新-每次发布" aria-label="Permalink to &quot;发布时的更新（每次发布）&quot;">​</a></h2><ol><li>从 <code>dist/</code> 读取资产，计算 SHA256 + 大小。</li><li><strong>门面</strong>：<code>assets/site-data.js</code>——更新 <code>dev</code> 频道块 （版本 / 构建 / 日期 / 资产四元组：名称、url、sha、 大小），并把这次发布插入 <code>history</code> 数组头部。</li><li><strong>页面</strong>：<code>download.html</code> + <code>index.html</code>——就地替换先前的 版本字符串（gh-pages 的 HTML 与归档的 release HTML 存在结构差异——不要整文件覆盖，只替换字符串）。</li><li><strong>OTA 清单</strong>：分支根的 <code>update.json</code>（版本、 构建、时间、变更文本、包 URL/sha/大小）——系统内 <code>checkupdate</code> 解析的就是它。</li><li><strong>downloads/</strong>：把四个发布资产复制进来（小写 <code>opencube-&lt;ver&gt;.*</code> 规范名）。</li><li>两个提交（门面 + downloads）并推送分支。</li></ol><h2 id="运行后的验证" tabindex="-1">运行后的验证 <a class="header-anchor" href="#运行后的验证" aria-label="Permalink to &quot;运行后的验证&quot;">​</a></h2><ul><li><code>https://ocos.cubestudio.cn/update.json</code> 显示新的 版本/构建/sha。</li><li>下载页的四个哈希与 Release 的四个相等。</li><li>每个资产上 <code>curl -sL &lt;asset-url&gt; | sha256sum</code> 的结果等于 其声明的 SHA256。</li><li>OTA E2E（<code>tools/run_fix4_regression.py</code> 的 update 节 + checkupdate 流程）在以较低构建号构建的机器上看到 &quot;New version available.&quot;。</li></ul><h2 id="数字从哪里来" tabindex="-1">数字从哪里来 <a class="header-anchor" href="#数字从哪里来" aria-label="Permalink to &quot;数字从哪里来&quot;">​</a></h2><p><code>tools/update_website.sh &lt;version&gt; &lt;build&gt; [date-iso] [changes]</code> 从 <code>dist/</code> 计算 SHA256/大小集合并写入数据文件（任何地方都 不手改版本号）——GitHub Release 正文与私有镜像审计记录 携带的是同一组数字，因此网站 / Release / 镜像持有逐字节 一致的副本。</p>',8)])])}const _=o(d,[["render",l]]);export{p as __pageData,_ as default};
